    (v_route, 'Swedish Army Museum', 'Vojenská historie ve Švédsku — opevnění, technika a příběhy, které stojí za zastávku.', 59.33472, 18.08018, 'http://commons.wikimedia.org/wiki/Special:FilePath/Arm%C3%A9museum%202014%2001.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Arm%C3%A9museum%202014%2001.JPG"}'::text[], 0, '{"en": {"name": "Swedish Army Museum", "description": "Military history of Sweden in Stockholm. Military history in Sweden — fortifications, hardware and stories worth the stop."}, "de": {"name": "Schwedisches Armeemuseum", "description": "Museum zur schwedischen Militärgeschichte in Stockholm. Militärgeschichte in Schweden — Befestigungen, Technik und Geschichten, die den Halt lohnen."}, "pl": {"name": "Muzeum Armii w Sztokholmie", "description": "Muzeum w Szwecji. Historia wojskowa w Szwecji — fortyfikacje, sprzęt i historie warte postoju."}, "nl": {"name": "Zweeds legermuseum", "description": "Vertonen militaire geschiedenis van Zweden, vanaf de 16e eeuw tot heden. Er zijn ook ongeveer 5000 trofeeën, voornamelijk uit de Dertigjarige Oorlog. Militaire geschiedenis in Zweden — vestingwerken, materieel en verhalen die de stop waard zijn."}, "es": {"name": "Museo del Ejército de Suecia", "description": "Museo en Estocolmo, Suecia. Historia militar en Suecia: fortificaciones, material y relatos que merecen la parada."}, "fr": {"name": "musée de l''Armée", "description": "Musée à Stockholm, en Suède. Histoire militaire en Suède — fortifications, matériel et récits qui valent l''arrêt."}, "uk": {"name": "Музей шведської армії", "description": "Військова історія у Швеції — укріплення, техніка та історії, варті зупинки."}}'::jsonb),
