    (v_route, 'Naval Museum of Sweden', 'Vojenská historie ve Švédsku — opevnění, technika a příběhy, které stojí za zastávku.', 56.1614, 15.5995, 'http://commons.wikimedia.org/wiki/Special:FilePath/Marinmuseum%20Karlskrona%203ships%202015.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Marinmuseum%20Karlskrona%203ships%202015.jpg"}'::text[], 0, '{"en": {"name": "Naval Museum of Sweden", "description": "Military history museum in Karlskrona, Sweden. Military history in Sweden — fortifications, hardware and stories worth the stop."}, "de": {"name": "Marinemuseum von Schweden", "description": "Militärhistorisches Museum mit Fokus auf die schwedische Marineverteidigung und auf die Geschichte der schwedischen Marine. Militärgeschichte in Schweden — Befestigungen, Technik und Geschichten, die den Halt lohnen."}, "pl": {"name": "Marinmuseum", "description": "Historia wojskowa w Szwecji — fortyfikacje, sprzęt i historie warte postoju."}, "nl": {"name": "Marinemuseum van Zweden", "description": "Militair Historisch Museum met een focus op de Zweedse Marine Defensie, en op het verhaal van de Zweedse Marine. Militaire geschiedenis in Zweden — vestingwerken, materieel en verhalen die de stop waard zijn."}, "es": {"name": "Museo de la Armada de Suecia", "description": "Museo de historia militar con enfoque en la Defensa Naval de Suecia, y en la historia de la Armada de Suecia. Historia militar en Suecia: fortificaciones, material y relatos que merecen la parada."}, "fr": {"name": "musée de la marine", "description": "Musée à Karlskrona, Suède. Histoire militaire en Suède — fortifications, matériel et récits qui valent l''arrêt."}, "uk": {"name": "Naval Museum of Sweden", "description": "Військова історія у Швеції — укріплення, техніка та історії, варті зупинки."}}'::jsonb),
    (v_route, 'Kungsholms Fort', 'Vojenská historie ve Švédsku — opevnění, technika a příběhy, které stojí za zastávku.', 56.10797, 15.58877, 'http://commons.wikimedia.org/wiki/Special:FilePath/KungsholmsFortKarlskrona2.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/KungsholmsFortKarlskrona2.JPG"}'::text[], 1, '{"en": {"name": "Kungsholms Fort", "description": "Military history in Sweden — fortifications, hardware and stories worth the stop."}, "de": {"name": "Kungsholms Fort", "description": "Militärgeschichte in Schweden — Befestigungen, Technik und Geschichten, die den Halt lohnen."}, "pl": {"name": "Kungsholms", "description": "Historia wojskowa w Szwecji — fortyfikacje, sprzęt i historie warte postoju."}, "nl": {"name": "Kungsholms Fort", "description": "Militaire geschiedenis in Zweden — vestingwerken, materieel en verhalen die de stop waard zijn."}, "es": {"name": "Kungsholms Fort", "description": "Historia militar en Suecia: fortificaciones, material y relatos que merecen la parada."}, "fr": {"name": "Kungsholms Fort", "description": "Histoire militaire en Suède — fortifications, matériel et récits qui valent l''arrêt."}, "uk": {"name": "Kungsholms Fort", "description": "Військова історія у Швеції — укріплення, техніка та історії, варті зупинки."}}'::jsonb),
    (v_route, 'Drottningskär Citadel', 'Vojenská historie ve Švédsku — opevnění, technika a příběhy, které stojí za zastávku.', 56.11017, 15.56434, 'http://commons.wikimedia.org/wiki/Special:FilePath/Drottningsk%C3%A4rs%20kastell%20daytime%20shore%20view.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Drottningsk%C3%A4rs%20kastell%20daytime%20shore%20view.jpg"}'::text[], 2, '{"en": {"name": "Drottningskär Citadel", "description": "Part of the naval base in Karlskrona and built 1680-1750 by military architect Erik Dahlbergh. Military history in Sweden — fortifications, hardware and stories worth the stop."}, "de": {"name": "Festung Drottningskär", "description": "Ehemalige Festungsanlage (heute Museum) am Aspösund; in Drottningskär, Schweden. Militärgeschichte in Schweden — Befestigungen, Technik und Geschichten, die den Halt lohnen."}, "pl": {"name": "Zamek Drottningskär", "description": "Historia wojskowa w Szwecji — fortyfikacje, sprzęt i historie warte postoju."}, "nl": {"name": "Kasteel Drottningskär", "description": "Werd in 1680 een aanvang gemaakt. Het moest de belangrijke vaarweg naar de nieuwe marinebasis in Karlskrona beschermen. Militaire geschiedenis in Zweden — vestingwerken, materieel en verhalen die de stop waard zijn."}, "es": {"name": "Drottningskär Citadel", "description": "Historia militar en Suecia: fortificaciones, material y relatos que merecen la parada."}, "fr": {"name": "Drottningskär Citadel", "description": "Bâtiment de la commune de Karlskrona, Blekinge, Suède. Histoire militaire en Suède — fortifications, matériel et récits qui valent l''arrêt."}, "uk": {"name": "Drottningskär Citadel", "description": "Військова історія у Швеції — укріплення, техніка та історії, варті зупинки."}}'::jsonb),
    (v_route, 'Karlshamns Castle', 'Vojenská historie ve Švédsku — opevnění, technika a příběhy, které stojí za zastávku.', 56.16006, 14.86561, 'http://commons.wikimedia.org/wiki/Special:FilePath/0441Karlshamns%20kastell.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/0441Karlshamns%20kastell.jpg"}'::text[], 3, '{"en": {"name": "Karlshamns Castle", "description": "Old fortification in Karlshamn, Blekinge, Sweden. Military history in Sweden — fortifications, hardware and stories worth the stop."}, "de": {"name": "Festung Karlshamn", "description": "Festung auf der Insel Frisholmen vor Karlshamn, Schweden. Militärgeschichte in Schweden — Befestigungen, Technik und Geschichten, die den Halt lohnen."}, "pl": {"name": "Karlshamns Kastell", "description": "Historia wojskowa w Szwecji — fortyfikacje, sprzęt i historie warte postoju."}, "nl": {"name": "Karlshamns Castle", "description": "Bouwwerk in Zweden. Militaire geschiedenis in Zweden — vestingwerken, materieel en verhalen die de stop waard zijn."}, "es": {"name": "Karlshamns Castle", "description": "Historia militar en Suecia: fortificaciones, material y relatos que merecen la parada."}, "fr": {"name": "Karlshamns Castle", "description": "Bâtiment de la commune de Karlshamn, Blekinge, Suède. Histoire militaire en Suède — fortifications, matériel et récits qui valent l''arrêt."}, "uk": {"name": "Karlshamns Castle", "description": "Військова історія у Швеції — укріплення, техніка та історії, варті зупинки."}}'::jsonb);
