    (v_route, 'Muzeum německé obranné techniky Bundeswehru', 'Muzeum v Německu. Vojenská historie v Německu — opevnění, technika a příběhy, které stojí za zastávku.', 50.36881, 7.58553, 'http://commons.wikimedia.org/wiki/Special:FilePath/Langemarck%20Kas%201.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Langemarck%20Kas%201.JPG"}'::text[], 0, '{"en": {"name": "Bundeswehr Museum of German Defense Technology", "description": "Military and defense technology museum of the Bundeswehr in Germany. Military history in Germany — fortifications, hardware and stories worth the stop."}, "de": {"name": "Wehrtechnische Studiensammlung Koblenz", "description": "Wehrtechnische Studiensammlung der Bundeswehr in Koblenz. Militärgeschichte in Deutschland — Befestigungen, Technik und Geschichten, die den Halt lohnen."}, "pl": {"name": "Wehrtechnische Studiensammlung Koblenz", "description": "Muzeum wojskowe w Koblencji. Historia wojskowa w Niemczech — fortyfikacje, sprzęt i historie warte postoju."}, "nl": {"name": "Wehrtechnische Studiensammlung Koblenz", "description": "Technische tentoonstelling in Duitsland. Militaire geschiedenis in Duitsland — vestingwerken, materieel en verhalen die de stop waard zijn."}, "es": {"name": "Muzeum německé obranné techniky Bundeswehru", "description": "Historia militar en Alemania: fortificaciones, material y relatos que merecen la parada."}, "fr": {"name": "musée de l''armement de la Bundeswehr", "description": "Musée officielle d''études de la technique de défense de la Bundeswehr. Histoire militaire en Allemagne — fortifications, matériel et récits qui valent l''arrêt."}, "uk": {"name": "Музей німецької оборонної техніки Бундесверу", "description": "Музей військової та оборонної техніки Бундесверу в Німеччині. Військова історія в Німеччині — укріплення, техніка та історії, варті зупинки."}}'::jsonb),
    (v_route, 'Emperor Franz Stronghold', 'Vojenská historie v Německu — opevnění, technika a příběhy, které stojí za zastávku.', 50.3707, 7.59101, 'http://commons.wikimedia.org/wiki/Special:FilePath/Feste%20Franz%20Innenhof%202008.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Feste%20Franz%20Innenhof%202008.JPG"}'::text[], 1, '{"en": {"name": "Emperor Franz Stronghold", "description": "Was built in 1822 as the part of Koblenz Fortress. Military history in Germany — fortifications, hardware and stories worth the stop."}, "de": {"name": "Feste Kaiser Franz", "description": "Wurde 1822 als Teil der Festung Koblenz erbaut. Militärgeschichte in Deutschland — Befestigungen, Technik und Geschichten, die den Halt lohnen."}, "pl": {"name": "Emperor Franz Stronghold", "description": "Historia wojskowa w Niemczech — fortyfikacje, sprzęt i historie warte postoju."}, "nl": {"name": "Kaiser Franz Bolwerk", "description": "Werd gebouwd in 1822 als onderdeel van het vesting van Koblenz. Militaire geschiedenis in Duitsland — vestingwerken, materieel en verhalen die de stop waard zijn."}, "es": {"name": "Emperor Franz Stronghold", "description": "Historia militar en Alemania: fortificaciones, material y relatos que merecen la parada."}, "fr": {"name": "Emperor Franz Stronghold", "description": "Histoire militaire en Allemagne — fortifications, matériel et récits qui valent l''arrêt."}, "uk": {"name": "Emperor Franz Stronghold", "description": "Військова історія в Німеччині — укріплення, техніка та історії, варті зупинки."}}'::jsonb),
